import { emit } from './events';

let currentPath = window.location.pathname + window.location.hash;
let scheduled = false;

function getRoute() {
    const path = window.location.pathname;
    const hash = window.location.hash;

    return {
        path,
        hash,
        full: path + hash,
        isLogin: hash.includes('/login') || path.includes('/login'),
        isHome: hash === '#/home.html' || hash.includes('/home'),
        isDashboard: hash.includes('/dashboard') || path.includes('/dashboard'),
        isSettings: hash.includes('/settings') || path.includes('/settings'),
        isDetails: hash.includes('/details') || hash.includes('/item'),
        isPlayback: document.documentElement.classList.contains('ptv-playing')
    };
}

function checkRoute() {
    scheduled = false;

    const nextPath = window.location.pathname + window.location.hash;

    if (nextPath === currentPath) {
        return;
    }

    currentPath = nextPath;

    const route = getRoute();

    document.documentElement.classList.toggle('ptv-route-login', route.isLogin);
    document.documentElement.classList.toggle('ptv-route-home', route.isHome);
    document.documentElement.classList.toggle('ptv-route-dashboard', route.isDashboard);
    document.documentElement.classList.toggle('ptv-route-settings', route.isSettings);
    document.documentElement.classList.toggle('ptv-route-details', route.isDetails);

    emit('routechange', route);
}

function scheduleRouteCheck() {
    if (scheduled) return;

    scheduled = true;
    requestAnimationFrame(checkRoute);
}

export function currentRoute() {
    return getRoute();
}

export function startRouter() {
    window.addEventListener('hashchange', scheduleRouteCheck);
    window.addEventListener('popstate', scheduleRouteCheck);

    const originalPushState = history.pushState;
    const originalReplaceState = history.replaceState;

    history.pushState = function (...args) {
        const result = originalPushState.apply(this, args);
        scheduleRouteCheck();
        return result;
    };

    history.replaceState = function (...args) {
        const result = originalReplaceState.apply(this, args);
        scheduleRouteCheck();
        return result;
    };

    checkRoute();
}

startRouter();
